package in.recallradar;
import jakarta.persistence.*; import java.time.*; import java.util.*;
enum IncidentStatus{OPEN,CONTAINED,CLOSED} enum IncidentSeverity{LOW,MEDIUM,HIGH,CRITICAL}
@Entity @Table(name="incident") class Incident{@Id UUID id;UUID organizationId;String title;@Enumerated(EnumType.STRING)IncidentStatus status;@Enumerated(EnumType.STRING)IncidentSeverity severity;Instant createdAt;UUID createdBy;protected Incident(){}Incident(UUID org,String title,IncidentSeverity severity,UUID actor){id=UUID.randomUUID();organizationId=org;this.title=title;this.severity=severity;status=IncidentStatus.OPEN;createdAt=Instant.now();createdBy=actor;}}
@Entity @Table(name="lot_quarantine") class LotQuarantine{@Id UUID id;UUID incidentId;UUID lotId;boolean active=true;String reason;Instant createdAt;Instant releasedAt;protected LotQuarantine(){}LotQuarantine(UUID incident,UUID lot,String reason){id=UUID.randomUUID();incidentId=incident;lotId=lot;this.reason=reason;createdAt=Instant.now();}void release(){active=false;releasedAt=Instant.now();}}
@Entity @Table(name="corrective_action") class CorrectiveAction{@Id UUID id;UUID incidentId;String description;boolean completed=false;Instant createdAt;Instant completedAt;protected CorrectiveAction(){}CorrectiveAction(UUID incident,String text){id=UUID.randomUUID();incidentId=incident;description=text;createdAt=Instant.now();}void complete(){completed=true;completedAt=Instant.now();}}
